function testHostToKernelShapesAndLosslessJson(): void {
  for (const message of [...makeMessagesToKernel(), ...makeFailureMessagesToKernel()]) {
    assert.throws(
      () => parseAppsHostMessageToKernel({ ...message, invalidJson: -0 }),
      /lossless JSON value/,
    );
  }

  const ready = makeMessagesToKernel()[0];
  assert.ok(ready);
  for (const port of [0, 1.5, 65_536]) {
    assert.throws(
      () =>
        parseAppsHostMessageToKernel({
          ...ready,
          apps: [
            {
              appId: 'app',
              frontend: {
                port,
                baseUrl: 'http://localhost',
                wsUrl: null,
              },
            },
          ],
        }),
      /integer between 1 and 65535/,
    );
  }

  assert.throws(
    () =>
      parseAppsHostMessageToKernel({
        type: 'log',
        level: 'info',
        msg: 'value',
        appId: null,
        data: [],
      }),
    /data: must be a lossless JSON object/,
  );

  const tool = makeMessagesToKernel()[2];
  assert.ok(tool);
  assert.throws(
    () =>
      parseAppsHostMessageToKernel({
        ...tool,
        output: { content: 'value', outcome: 'unknown' },
      }),
    /outcome/,
  );
  assert.throws(
    () =>
      parseAppsHostMessageToKernel({
        ...tool,
        output: {
          content: 'value',
          outcome: 'success',
          contentItems: [
            {
              type: 'input_image',
              mimeType: 'image/png',
              byteLength: 1.5,
              artifact: {
                rootId: 'root-1',
                selfId: 'dialog-1',
                status: 'running',
                relPath: 'artifacts/image.png',
              },
            },
          ],
        },
      }),
    /non-negative integer/,
  );

  assert.throws(
    () =>
      parseAppsHostMessageToKernel({
        ...tool,
        reminderRequests: [
          {
            kind: 'delete',
            ownerRef: 'owner-1',
            meta: { invalid: -0 },
          },
        ],
      }),
    /lossless JSON value/,
  );

  let accessorReads = 0;
  const dataWithAccessor: Record<string, unknown> = {};
  Object.defineProperty(dataWithAccessor, 'value', {
    enumerable: true,
    get: () => {
      accessorReads += 1;
      return 42;
    },
  });
  assert.throws(
    () =>
      parseAppsHostMessageToKernel({
        type: 'log',
        level: 'info',
        msg: 'value',
        appId: null,
        data: dataWithAccessor,
      }),
    /lossless JSON value/,
  );
  assert.equal(accessorReads, 0, 'IPC validation must not evaluate accessors');

  assert.throws(
    () =>
      parseAppsHostMessageToKernel({
        type: 'reminder_apply_result',
        callId: 'call',
        ok: true,
        result: { treatment: 'update', ownedIndex: -1, reminder: makeReminderState() },
      }),
    /non-negative integer/,
  );
  assert.throws(
    () =>
      parseAppsHostMessageToKernel({
        type: 'reminder_update_result',
        callId: 'call',
        ok: true,
        result: { treatment: 'update', updatedContent: 42 },
      }),
    /updatedContent/,
  );
  assert.throws(
    () =>
      parseAppsHostMessageToKernel({
        type: 'reminder_render_result',
        callId: 'call',
        ok: true,
        message: { content: 'value', unsupportedExtension: true },
      }),
    /unsupported properties: unsupportedExtension/,
  );
}

