                rootAbs: slowAppRootAbs,
              },
              host: {
                kind: 'node_module',
                moduleRelPath: './src/app.js',
                exportName: 'createDomindsApp',
              },
              contributes: {},
            },
          },
        ],
      }),
    );

    const returnStartedAt = process.hrtime.bigint();
    const returnedBeforeSlowAppReady = await startServer({
      port: 0,
