              wsUrl: null,
              unsupportedExtension: true,
            },
          },
        ],
      }),
    Error,
  );

  const tool = makeMessagesToKernel()[2];
  assert.ok(tool);
  assert.throws(
    () =>
      parseAppsHostMessageToKernel({
        ...tool,
        output: {
          content: 'value',
          outcome: 'success',
          contentItems: [
            {
              type: 'input_text',
              text: 'value',
              unsupportedExtension: true,
            },
          ],
        },
      }),
    Error,
  );
  assert.throws(
    () =>
      parseAppsHostMessageToKernel({
        ...tool,
        output: {
          ...(tool['output'] as Record<string, unknown>),
          unsupportedExtension: true,
        },
      }),
    Error,
  );

  const contentItemBase = {
    type: 'input_image',
    mimeType: 'image/png',
    byteLength: 1,
    artifact: {
      rootId: 'root-1',
      selfId: 'dialog-1',
      status: 'completed',
      relPath: 'artifacts/image.png',
    },
  };
  assert.throws(
    () =>
      parseAppsHostMessageToKernel({
        ...tool,
        output: {
          content: 'value',
          outcome: 'success',
          contentItems: [{ ...contentItemBase, unsupportedExtension: true }],
        },
      }),
    Error,
  );
  assert.throws(
    () =>
      parseAppsHostMessageToKernel({
        ...tool,
        output: {
          content: 'value',
          outcome: 'success',
          contentItems: [
            {
              ...contentItemBase,
              artifact: {
                ...contentItemBase.artifact,
                unsupportedExtension: true,
              },
            },
          ],
        },
      }),
    Error,
  );

  assert.throws(
    () =>
      parseAppsHostMessageToKernel({
        ...tool,
        reminderRequests: [
          {
            kind: 'delete',
            ownerRef: 'owner-1',
            unsupportedExtension: true,
          },
        ],
      }),
    Error,
  );
  assert.throws(
    () =>
      parseAppsHostMessageToKernel({
        ...tool,
        dialogReminderRequests: [
          {
            target: { dialogId: 'dialog-1' },
            reminderRequests: [],
            unsupportedExtension: true,
          },
        ],
      }),
    Error,
  );
  assert.throws(
    () =>
      parseAppsHostMessageToKernel({
        ...tool,
        dialogReminderRequests: [
          {
            target: { dialogId: 'dialog-1', unsupportedExtension: true },
            reminderRequests: [],
          },
        ],
      }),
    Error,
  );

  const apply = makeMessagesToKernel()[3];
  assert.ok(apply);
  const applyResult = apply['result'] as Record<string, unknown>;
  assert.throws(
    () =>
